func testProdutoFichatecnicaToOneSetOpProdutoUsingPro(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a ProdutoFichatecnica
	var b, c Produto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, produtoFichatecnicaDBTypes, false, strmangle.SetComplement(produtoFichatecnicaPrimaryKeyColumns, produtoFichatecnicaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Produto{&b, &c} {
		err = a.SetPro(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Pro != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.ProProdutoFichatecnicas[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.ProID != x.ProID {
			t.Error("foreign key was wrong value", a.ProID)
		}

		if exists, err := ProdutoFichatecnicaExists(ctx, tx, a.ProID, a.ProProID); err != nil {
			t.Fatal(err)
		} else if !exists {
			t.Error("want 'a' to exist")
		}

	}
}

